# Own-wording feats of Valda's Spire of Secrets (2014 rules), part A. Shapes follow thhw_feat_a.py.
ALSO = []
NH = "Near-Human, 1st level only"
ANY = ["STR", "DEX", "CON", "INT", "WIS", "CHA"]
CC = "Character creation only"
FEATS = {
 "Aberrant Spawn": {"d": "Aberration mutation: Advantage against charm and mind reading, Psychic resistance, and a tentacle limb that makes 1d6 unarmed strikes.", "pre": NH, "asi": ANY,
   "full": "**Aberrant Mind.** You have Advantage on saves to avoid or end the charmed condition on you and against any effect that senses your emotions or reads your thoughts.\n**Psychic Resistance.** You have Resistance to Psychic damage.\n**Tentacle.** One limb is a rubbery tentacle you can use for unarmed strikes. A hit deals 1d6 + your Strength modifier bludgeoning damage.",
   "fx": {"res": ["Psychic"], "notes": [["Note", "Aberrant Mind: Advantage on saves against charm and against effects that sense emotions or read thoughts"]]}},
 "Aquanaut": {"d": "Breathe air and water, and swim at your walking Speed.", "pre": NH, "asi": ANY,
   "full": "**Aquatic.** You can breathe air and water.\n**Finned.** You have a swimming Speed equal to your walking Speed.",
   "fx": {"mv": {"swim": "speed"}}},
 "Arachne": {"d": "Eight-eyed drow-touched human: Darkvision 120 ft, Poison Spray, then Bane and Spider Climb once each per Long Rest.", "pre": NH, "asi": ANY,
   "full": "**Darkvision.** You see in dim light within 120 feet as if bright, and in darkness as if dim. You see only shades of gray in darkness.\n**Spider Magic.** You know the Poison Spray cantrip. At level 3 you can cast Bane once with this trait, and at level 5 Spider Climb once. A Long Rest restores each. You can also cast them with slots of the right level. Choose Intelligence, Wisdom or Charisma as the spellcasting ability when you take the feat.", "lu": {"n": "Spider Magic", "max": 2, "reset": "long", "tag": "Bane (lvl 3), Spider Climb (lvl 5)"}},
 "Arcane Preparation": {"d": "Wizard-style fixed slots: assign a spell to each slot, plus one free bonus slot per level.", "pre": "Spellcasting from Cleric, Druid or Wizard. " + CC,
   "full": "Instead of preparing spells, you fix each spell slot to one spell when you finish a Long Rest, picking from spells you could cast with it. A slot can be spent only on its assigned spell, but any slot can be recovered normally. You also gain one bonus slot of each level you have slots for, which has no assigned spell and can cast any spell you know. For example, a level 3 wizard assigns four 1st-level slots and two 2nd-level slots, and also has one bonus 1st-level and one bonus 2nd-level slot that can cast any spell in the spellbook."},
 "Battle Adept": {"d": "One d6 battle die and two maneuvers from the Captain or the Grey Watchman Warden.", "asi": ["STR", "DEX"],
   "full": "You gain one battle die (d6), added to any battle dice you already have. It is spent when used. A short or long rest, or rolling initiative, restores all battle dice.\nYou learn two maneuvers from the Captain class or the Grey Watchman Warden. If a maneuver forces a save, the DC is 8 + your Proficiency Bonus + your Strength or Dexterity modifier.",
   "lu": {"n": "Battle Adept: battle die", "max": 1, "reset": "short", "tag": "d6. Also on initiative"}},
 "Beastman": {"d": "Claws for 1d6 slashing unarmed strikes and Advantage on Perception checks to smell.", "pre": NH, "asi": ANY,
   "full": "**Claws.** Your claws make unarmed strikes that deal 1d6 + your Strength modifier slashing damage.\n**Keen Smell.** You have Advantage on Wisdom (Perception) checks that rely on smell.",
   "fx": {"notes": [["Note", "Keen Smell: Advantage on Wisdom (Perception) checks that rely on smell"]]}},
 "Bounty Hunter": {"d": "Mark a creature for 1 hour to track it, remember every face, and knock out instead of kill.", "asi": ["WIS"],
   "full": "**Perfect Recall.** You remember the name and face of everyone you have ever met.\n**Mark.** As an action, mark a creature you see within 120 feet for 1 hour. You have Advantage on Wisdom (Perception) and Wisdom (Survival) checks to find it, and you can tell whether it has passed through a place. Only one creature at a time.\n**Bring Them In.** When you reduce a creature to 0 hit points with an attack or spell, you can knock it out instead of killing it.", "act": "action"},
 "Brutal Grip": {"d": "Two-handed damage die with versatile weapons held in one hand, and one-handed use of two-handed weapons at a penalty.", "asi": ["STR"],
   "full": "When you wield a versatile weapon in one hand, you can use its two-handed damage die. You can wield a two-handed melee weapon in one hand, treating it as one-handed, but you have Disadvantage on attack rolls made that way."},
 "Cantrip Specialist": {"d": "Learn two of eight Warmage cantrip tricks. Character level counts as warmage level.", "pre": "Ability to cast a cantrip",
   "full": "You learn two Warmage tricks from this list: Blasting Cantrip, Corrosive Cantrip, Draining Cantrip, Explosive Cantrip, Icy Cantrip, Severe Cantrip, Silent Cantrip, Static Cantrip. Your cantrips count as warmage cantrips for these tricks, and your character level counts as your warmage level where the trick needs it."},
 "Child": {"d": "Small size, two fewer skills, Strength and Constitution capped at 16, and two saving throw proficiencies.", "pre": CC,
   "full": "You are an adolescent with no place in the dangerous adventuring life. Your size is Small, even if your species is normally Medium. You have two fewer skill proficiencies than other characters of your class. Your Strength and Constitution maximum is 16, not 20. You gain proficiency in two saving throws of your choice."},
 "Chronomancy Initiate": {"d": "Chronomancy spells join your list, learn Moment to Think, and four chronomancy spells that never count against your spells.", "pre": "Spellcasting",
   "full": "All spells with the chronomancy tag join your class's spell list if they are of a level your class gets slots for, using your spellcasting ability. You learn the Moment to Think cantrip, which does not count against cantrips known. You learn four chronomancy spells that you cast with this feat. If you prepare spells they are always prepared and do not count against your limit. A wizard adds them to the spellbook at no cost. If you learn spells they do not count against spells known. When you gain a level in your spellcasting class, you can swap one of them for another chronomancy spell of a level you have slots for."},
 "Dilettante": {"d": "After a Long Rest, spend 10 minutes to gain a weapon, skill or tool proficiency, or a wizard cantrip, until your next Long Rest.",
   "full": "When you finish a Long Rest you can spend 10 minutes practicing. Pick a simple or martial weapon, a skill, a tool, or a wizard cantrip. You gain proficiency with that weapon, skill or tool, or you learn the cantrip and cast it with Intelligence, until you finish a Long Rest."},
 "Diminutive": {"d": "You are Small, and squeeze through Tiny gaps without penalty.", "pre": "Medium size. " + CC,
   "full": "You were born much smaller than your people, or never grew to full height. You are Small instead of Medium. You take no penalty for squeezing through a space only large enough for a Tiny creature."},
 "Downcaster": {"d": "Four extra spells of level 3 or lower and the power to split a slot into lower slots.", "pre": "Spellcasting",
   "full": "If you learn spells, you learn four spells of 3rd level or lower from your class list, of levels you have slots for. They do not count against spells known. As an action you can split a spell slot of 5th level or lower into two or more lower slots whose combined level is no more than the original. Slots made this way vanish when you recover slots after a short or long rest."},
 "Dual-Soul": {"d": "Two souls share your body with separate personalities, backgrounds, skills and languages. They swap on odd d20 rolls after a Long Rest.", "pre": CC,
   "full": "Two souls fight for control of your body. You keep two sets of personality traits, ideals, bonds and flaws, and the souls have different names. They talk to each other telepathically, but only one controls the body at a time. The other can see through your eyes and hear through your ears. When you finish a Long Rest, roll a d20. On an odd roll, the soul in control switches. Each soul has its own background with different skill and tool proficiencies and different languages. You have only the skills, tools and languages of the soul in control."},
 "Early Riser": {"d": "Long rest in 4 hours, short rest in 30 minutes, and regain all Hit Dice on a Long Rest.",
   "full": "A strict routine lets you rest less. You gain the full benefit of a Long Rest in 4 hours and of a Short Rest in 30 minutes. When you finish a Long Rest you regain all expended Hit Dice, not half."},
 "Elderly": {"d": "Pick any number of benefits and an equal number of drawbacks from two tables of old age.", "pre": CC,
   "full": "Old age catches up with you, though you are not done adventuring. Choose or roll for any number of benefits from the first table, even none, and the same number of drawbacks from the second.\n**Benefits.** 1: proficiency in History or Insight. 2: proficiency in two sets of artisan's tools. 3: you can always add your Proficiency Bonus to saves against being charmed.\n**Drawbacks.** 1: bad back, your lifting and carrying capacity is halved. 2: forgetful, a roll of 13 on the d20 for an Intelligence check counts as 1. 3: poor eyesight, Disadvantage on Wisdom (Perception) checks that rely on sight."},
 "Exotic Mastery": {"d": "Proficiency with exotic armor and four exotic weapons of your choice.", "pre": "Proficiency with martial weapons",
   "full": "You have trained with unusual weapons and armor of irregular design. You gain proficiency with exotic armor and four exotic weapons of your choice."},
 "Favorite Spell": {"d": "Pick a spell of 5th level or lower: it casts one level higher with a slot, cannot be counterspelled, and is free once per Long Rest.", "pre": "Spellcasting ability 15 or higher",
   "full": "Pick a spell you can cast, of 5th level or lower, as your favorite. You can take this feat several times, picking a different spell each time.\nWhen you cast it, you can add a harmless impressive visual effect such as a shower of sparks. When you cast it with a slot, you can treat it as cast with a slot one level higher, up to 9th. It cannot be counterspelled. You can cast it once at its lowest level with no slot, and a Long Rest restores that.",
   "lu": {"n": "Favorite Spell: free cast", "max": 1, "reset": "long", "tag": "No slot"}},
 "Fickle Fortune": {"d": "Track rolls of 10 or lower on the d20. After three in a row, change the next d20 to a 20 (no crit).",
   "full": "Record each time you roll 10 or lower on the d20 for an attack roll, ability check or saving throw. If you roll 10 or lower three or more times in a row, you can change the d20 roll to a 20 right away. If it was an attack roll, it does not score a critical hit."},
 "Field Commander": {"d": "Order an ally to act with a reaction, and deny enemies Advantage against you while two allies are near.", "asi": ["CHA"],
   "full": "As an action, give an order to an ally within 60 feet that hears you. The ally can use its reaction to take one of these actions: Attack (one attack only), Dash, Disengage, Dodge, Help, Hide, Search or Use an Object.\nWhile you are within 5 feet of two or more allies who are not incapacitated, hostile creatures cannot gain Advantage on attack rolls against you.", "act": "action"},
 "Firebrand": {"d": "Fire-marked human: Fire resistance, Produce Flame, then Burning Hands and Flaming Sphere once each per Long Rest.", "pre": NH, "asi": ANY,
   "full": "**Fire Resistance.** You have Resistance to Fire damage.\n**Flame Magic.** You know the Produce Flame cantrip. At level 3 you can cast Burning Hands once with this trait, and at level 5 Flaming Sphere once, with no material component. A Long Rest restores each. You can also cast them with slots of the right level. Choose Intelligence, Wisdom or Charisma as the spellcasting ability when you take the feat.",
   "fx": {"res": ["Fire"]}, "lu": {"n": "Flame Magic", "max": 2, "reset": "long", "tag": "Burning Hands (lvl 3), Flaming Sphere (lvl 5)"}},
 "Focused Critical": {"d": "Pick ranged or melee weapon attacks: they crit on a 19 or 20.",
   "full": "Pick ranged weapon attacks or melee weapon attacks when you take this feat. Attack rolls of that type score a critical hit on a roll of 19 or 20."},
 "Gambler": {"d": "Proficiency with all gaming sets and bet on damage rolls once per turn.",
   "full": "You gain proficiency with all gaming sets and have Advantage on ability checks for games of chance.\nOnce on each of your turns, before you roll damage, you can place a stake on the roll. Pick below the average, or at or above the average. If you guessed right, add one extra damage die. If you guessed wrong, remove the highest damage die."},
 "Greenskin": {"d": "Photosynthetic skin: natural armor 12 + Dex, Advantage against poison, Poison resistance.", "pre": NH, "asi": ANY,
   "full": "**Natural Armor.** Without armor, your base AC is 12 + your Dexterity modifier. You can use it if worn armor would give a lower AC. A shield works as normal.\n**Photosynthetic Resilience.** You have Advantage on saves to avoid or end the poisoned condition on you, and Resistance to Poison damage.",
   "fx": {"res": ["Poison"], "notes": [["Note", "Natural Armor: with no armor your base AC is 12 + Dexterity modifier"]]}},
 "Grendel": {"d": "Goblinoid-human mix: Small or Medium, Darkvision 60 ft, Fey Ancestry, and bonus on your first combat turn.", "pre": NH, "asi": ANY,
   "full": "**Size.** You are Medium or Small, depending on your heritage.\n**Darkvision.** You see in dim light within 60 feet as if bright, and in darkness as if dim. You see only shades of gray in darkness.\n**Fey Ancestry.** You have Advantage on saves to avoid or end the charmed condition on you.\n**Grendel Ambition.** On your first turn in combat, you add your Proficiency Bonus to attack rolls, ability checks and saving throws."},
 "Grue": {"d": "Shadow-touched human: Darkvision 60 ft and a free reroll of Stealth after being found.", "pre": NH, "asi": ANY,
   "full": "**Darkvision.** You see in dim light within 60 feet as if bright, and in darkness as if dim. You see only shades of gray in darkness.\n**Covert.** When you are hidden and a creature finds you with a successful Wisdom (Perception) check, you can reroll your Dexterity (Stealth) check to hide. On a success you silently move and the creature does not notice you. A Short or Long Rest restores it.",
   "lu": {"n": "Covert", "max": 1, "reset": "short", "tag": "Reroll hide"}},
 "Gun-Mage Adept": {"d": "Four firearm proficiencies, firearms as focuses, renaissance spells and a finger guns or Concealed Shot cantrip.", "pre": "Spellcasting",
   "full": "You gain proficiency with four simple or martial firearms and can use them as spellcasting focuses. All spells with the renaissance tag join your class's spell list if they are of a level your class gets slots for, using your spellcasting ability. You learn either Concealed Shot or Finger Guns, which does not count against cantrips known. You learn four renaissance spells you cast with this feat. If you prepare spells they are always prepared and do not count against your limit. A wizard adds them to the spellbook at no cost. If you learn spells they do not count against spells known. When you gain a level in your spellcasting class, you can swap one of them for another renaissance spell of a level you have slots for."},
 "Hexer": {"d": "Two witch hexes and Cackle, using Charisma.", "pre": "Charisma 13",
   "full": "You learn two hexes of your choice from the witch class list and gain the Witch's Cackle feature. Use Charisma for the attack rolls and saving throws of these hexes."},
 "Homebrewer": {"d": "Alchemist's supplies and reagent dice equal to your Proficiency Bonus to brew potions of a 3rd-level alchemist.",
   "full": "You gain proficiency with alchemist's supplies if you lack it. Using a set over 10 minutes you can brew potions. You gain reagent dice equal to your Proficiency Bonus and can spend them to brew any potion an alchemist of level 3 can. They lose potency after 24 hours. If you have the alchemist's Reagent feature, you can also spend these dice to add damage to a bomb.",
   "lu": {"n": "Homebrewer: reagent dice", "max": "pb", "reset": "long", "tag": "Brew potions"}},
 "Hunted": {"d": "+5 passive Perception and instant waking, but 1 in 20 chance a Long Rest is only a Short Rest.", "pre": CC,
   "full": "Someone would kill you on sight or drag you to a bad end. The constant paranoia gives you +5 to your passive Wisdom (Perception) and wakes you at once when a creature moves within 30 feet. You rarely sleep soundly. Roll a d20 when you take a Long Rest. On a 1 you get only the benefits of a Short Rest. If you are sure your pursuers are gone for good, such as by leaving the plane or watching your hunter die, you lose this feat.",
   "fx": {"notes": [["Note", "Hunted: +5 passive Wisdom (Perception)"]]}},
 "Immortal": {"d": "Never age, Advantage against disease and poison, Poison resistance.", "pre": NH, "asi": ANY,
   "full": "**Ageless.** You do not age, cannot be aged magically and suffer none of the frailty of old age. You cannot die of old age.\n**Immortal Resilience.** You have Advantage on saves to avoid or end diseases and the poisoned condition, and Resistance to Poison damage.",
   "fx": {"res": ["Poison"]}},
 "Impaired Vision": {"d": "Blinded but with 10 ft blindsight, limited spellcasting by hearing, and immunity to gaze effects.", "pre": CC,
   "full": "Injury, illness or birth leaves you unable to see as others do. You rely on hearing and aids such as a white cane. Your condition might range from total blindness to low vision.\nYou have the blinded condition, but attack rolls do not gain Advantage against you because of it. You have blindsight 10 feet. Inside that range you effectively see anything not behind cover, and you see an invisible creature there unless it hides from you.\nYou can cast spells that need you to see a target or area if it is within 30 feet, you have a direct line to it, and you can hear it if it is a creature. Beyond 30 feet you make an ability check with your spellcasting ability against DC 10 + the spell's level. On a success the spell works, otherwise it fails with no effect.\nYou are immune to spells and effects that require you to see, such as a medusa's Petrifying Gaze.\nIf your sight is ever restored, such as by Regenerate, you lose this feat. Talk with your GM about whether that fits your character.",
   "fx": {"senses": [["Blindsight", 10, ""]], "notes": [["Note", "Impaired Vision: you have the blinded condition. Spells that need sight work only on targets within 30 ft you can reach by a direct line or hear"]]}},
 "Insectoid": {"d": "Antennae give 10 ft blindsight, and lost limbs regrow in 24 hours.", "pre": NH, "asi": ANY,
   "full": "**Blindsight.** Your antennae give you blindsight 10 feet. Within it you effectively see anything not behind cover, even blinded or in darkness, and you see invisible creatures unless they hide.\n**Regenerative.** If a body part is amputated without killing you, you regrow it fully in 24 hours.",
   "fx": {"senses": [["Blindsight", 10, ""]]}},
 "Iron Hero": {"d": "+2 AC against higher-CR attackers, Advantage against whoever downed an ally, and cancel a legendary action.",
   "full": "When a creature with a Challenge Rating higher than your level attacks you, you have +2 AC. You have Advantage on attack rolls against any creature that reduced one of your allies to 0 hit points in the last round. When a hostile creature you see takes a legendary action, you can use your reaction to intercede and stop it. A Short or Long Rest restores that.",
   "lu": {"n": "Iron Hero: stop a legendary action", "max": 1, "reset": "short", "tag": "Reaction"}, "act": "reaction"},
 "Jinxed": {"d": "Pick a number from 2 to 19. When you or an attacker against you rolls it on the d20, it becomes a 1.", "pre": CC,
   "full": "You were born under a bad star or struck by a hex that damaged your luck. Pick a number from 2 to 19. When you roll that number on an ability check or attack roll, the d20 becomes a 1. When a creature rolls that number on an attack against you or on a contested ability check against you, its d20 also becomes a 1."},
 "Lower Limb Disability": {"d": "Needs a mobility aid, cannot Dash on difficult terrain, Advantage against being knocked prone or moved.", "pre": CC,
   "full": "Injury, illness or birth means you cannot walk as others do and rely on an aid for mobility, such as crutches, a wheelchair, or a mechanical or magical support. Work with the GM on what fits the setting.\nYou cannot take the Dash action on difficult terrain. You have Advantage on ability checks and saves made to avoid being knocked prone or moved against your will.\nIf your mobility is ever restored, such as by Regenerate, you lose this feat. Talk with your GM about whether that fits your character."},
}
